import { readFile, writeFile } from "node:fs/promises";

const modules = [
  "js/storage.js",
  "js/questions.js",
  "js/kebun-questions.js",
  "js/balap.js",
  "js/kebun.js",
  "js/core/router.js",
  "js/features/home/home.js",
  "js/features/balap/views.js",
  "js/features/kebun/views.js",
  "js/features/mathquest/config.js",
  "js/features/mathquest/state.js",
  "js/features/mathquest/engine.js",
  "js/features/mathquest/views.js",
  "js/main.js",
];

function makeClassic(source, path) {
  let output = source
    .replace(/^import .+;\n/gm, "")
    .replace(/^export default \w+;\n?/gm, "")
    .replace(/^export function /gm, "function ");

  if (path.endsWith("features/balap/views.js")) {
    output = output
      .replace("function renderPlay", "function renderBalapPlay")
      .replace("function renderResults", "function renderBalapResults");
  }
  if (path.endsWith("features/kebun/views.js")) {
    output = output
      .replace("function renderPlay", "function renderKebunPlay")
      .replace("function renderResults", "function renderKebunResults");
  }
  if (path.endsWith("features/mathquest/views.js")) {
    output = output
      .replace("function renderSetup", "function renderMathQuestSetup")
      .replace("function renderGame", "function renderMathQuestGame")
      .replace("function renderResults", "function renderMathQuestResults");
  }
  if (path.endsWith("features/mathquest/config.js")) {
    output = output.replace(/^export const /gm, "const ");
  }
  if (path.endsWith("features/mathquest/state.js")) {
    output = output.replace(/^export const /gm, "const ");
  }
  if (path.endsWith("features/mathquest/engine.js")) {
    output = output.replace(/^export function /gm, "function ");
  }
  if (path.endsWith("features/mathquest/views.js")) {
    output = output.replace(/^export function /gm, "function ");
  }
  return `\n/* ${path} */\n${output}`;
}

const sources = await Promise.all(modules.map(async (path) => ({ path, source: await readFile(path, "utf8") })));
const bundle = `/* Generated by scripts/build-file-bundle.mjs. Do not edit directly. */\n${sources.map(({ path, source }) => makeClassic(source, path)).join("\n")}`;
await writeFile("js/app.bundle.js", bundle);
